  id:"glucosef", name:"Glucose, Fasting", abbr:"FBS", cat:"elec",
  syn:["glucose","fbs","fasting blood sugar","sugar","blood sugar","diabetes","ogtt"],
  specimen:"Plasma (fluoride)", tube:{ id:"fluoride", vol:"2 mL", handling:"Grey top essential. Without fluoride, glycolysis lowers glucose by roughly 5–7% per hour at room temperature." },
  prep:{ fasting:"8–10 hours — water permitted", items:["Overnight fast of 8–10 h. Plain water is allowed; no tea, coffee, sugar or tobacco.","Take the sample before the morning dose of insulin or oral hypoglycaemic unless specifically instructed otherwise.","Do not fast longer than 16 h — prolonged fasting distorts the result.","For OGTT: 3 days of unrestricted carbohydrate (≥150 g/day) beforehand, then 75 g anhydrous glucose, remain seated, no smoking, sample at 0 and 120 min."],
    patient:["Fast for 8 to 10 hours overnight. Plain water is allowed and encouraged.","No tea, coffee, milk, sugar, juice, chewing gum or tobacco during the fast.","Do NOT take your morning diabetes tablet or insulin until after the blood sample is taken, unless your doctor has told you otherwise.","Do not fast for more than 16 hours.","If a glucose tolerance test is planned, eat normally for 3 days before, then remain seated and do not smoke during the 2-hour test."] },
