    id:"esr", name:"Erythrocyte Sedimentation Rate", abbr:"ESR", cat:"sepsis",
    syn:["esr","sed rate","erythrocyte sedimentation rate","westergren","inflammatory marker"],
    specimen:"Sodium citrate (black-top ESR tube) or EDTA, depending on method",
