    tube:{ id:"citrate", vol:"2.7 mL", handling:"Fill exactly to the line. Separate within 1 h — platelet factor 4 released from platelets neutralises heparin and falsely lowers the result." },
    prep:{ fasting:"Not required",
      items:["TIMING IS THE WHOLE TEST. For LMWH, draw 4 hours after a subcutaneous dose (peak). For unfractionated heparin infusion, draw at any time once steady state is reached, at least 6 h after a rate change.","Record the drug, the dose, the exact time it was given and the time of the draw — a level without these is uninterpretable.","Separate promptly; delayed separation falsely lowers the result."],
      patient:["The timing of this blood test relative to your injection matters — come at the time you are given, not earlier or later."] },
    assayDep:true,
    units:{ conv:"IU/mL", si:"IU/mL", factor:1 },
    ranges:[
      { rid:"r1", kind:"target", grp:"LMWH prophylaxis (4 h peak)", sex:"any", age:"adult", preg:null, conv:{lo:0.2,hi:0.5}, si:{lo:0.2,hi:0.5} },
      { rid:"r2", kind:"target", grp:"LMWH treatment, once daily (4 h peak)", sex:"any", age:"adult", preg:null, conv:{lo:1.0,hi:2.0}, si:{lo:1.0,hi:2.0} },
      { rid:"r3", kind:"target", grp:"LMWH treatment, twice daily (4 h peak)", sex:"any", age:"adult", preg:null, conv:{lo:0.6,hi:1.0}, si:{lo:0.6,hi:1.0} },
      { rid:"r4", kind:"target", grp:"Unfractionated heparin (therapeutic)", sex:"any", age:"adult", preg:null, conv:{lo:0.3,hi:0.7}, si:{lo:0.3,hi:0.7} }
    ],
    critical:null,
    inc:["Excessive heparin dose","Renal impairment — LMWH accumulates because it is renally cleared","Delayed sampling relative to the dose"],
    dec:["Insufficient dose","Antithrombin deficiency (for unfractionated heparin)","Delayed sample separation — platelet factor 4 neutralises heparin in the tube"],
    interf:["Delayed separation falsely lowers the result.","Assays calibrated for unfractionated heparin and for LMWH are different — the laboratory must know which drug the patient is on."],
    pearls:["Anti-Xa is the right test when the APTT cannot be trusted: lupus anticoagulant, raised factor VIII, baseline APTT abnormality, or marked heparin resistance.","Monitor LMWH only where the pharmacokinetics are unpredictable: pregnancy, extremes of body weight, significant renal impairment, and in children. Routine monitoring is otherwise unnecessary.","In pregnancy, LMWH requirements change as weight and renal clearance rise — anti-Xa guided dosing is used in women on treatment doses.","A level without a documented dose time is worthless. If the timing is unknown, repeat rather than interpret.","Anti-Xa does NOT reliably measure DOAC levels unless the assay is specifically calibrated for that drug."],
    rel:["aptt","ptinr","platelet","creatinine"],
    src:["Standard anti-Xa therapeutic target ranges for LMWH and unfractionated heparin"]
