    specimen:"EDTA plasma (BNP requires EDTA)",
    tube:{ id:"edta", vol:"2 mL", handling:"BNP is unstable — use EDTA (never serum), separate promptly and analyse within 4 h, or freeze. NT-proBNP is far more stable and is often preferred for this reason." },
    prep:{ fasting:"Not required",
      items:["Use an EDTA tube; BNP in serum degrades rapidly.","Record weight, renal function and atrial fibrillation — all shift the level.","Note sacubitril/valsartan therapy: it RAISES BNP (by inhibiting its breakdown) while lowering NT-proBNP. Use NT-proBNP to monitor these patients."],
      patient:[] },
    assayDep:true,
    units:{ conv:"pg/mL", si:"ng/L", factor:1 },
    ranges:[
      { rid:"r1", kind:"cutoff", grp:"Heart failure unlikely (non-acute)", sex:"any", age:"adult", preg:null, conv:{lo:null,hi:35}, si:{lo:null,hi:35} },
      { rid:"r2", kind:"cutoff", grp:"Heart failure unlikely (acute presentation)", sex:"any", age:"adult", preg:null, conv:{lo:null,hi:100}, si:{lo:null,hi:100} },
      { rid:"r3", kind:"cutoff", grp:"Refer / echocardiography indicated", sex:"any", age:"adult", preg:null, conv:{lo:100,hi:400}, si:{lo:100,hi:400} },
      { rid:"r4", kind:"cutoff", grp:"Heart failure likely", sex:"any", age:"adult", preg:null, conv:{lo:400,hi:null}, si:{lo:400,hi:null} }
    ],
    critical:null,
    inc:["Heart failure (systolic or diastolic)","Atrial fibrillation — raises BNP substantially and reduces its specificity","Pulmonary embolism, pulmonary hypertension, cor pulmonale","Chronic kidney disease (reduced clearance)","Sepsis, acute coronary syndrome, left ventricular hypertrophy","Increasing age; female sex","Sacubitril/valsartan (raises BNP specifically)"],
    dec:["Obesity — BNP is systematically LOWER in obese patients, and a 'normal' value may be falsely reassuring","Flash pulmonary oedema presenting very early, before the peptide rises","Pericardial constriction"],
    interf:["BNP degrades rapidly unless collected in EDTA and processed promptly.","Assays from different manufacturers are not interchangeable; BNP and NT-proBNP have completely different reference ranges and must not be compared."],
    pearls:["The main value is the NEGATIVE predictive value. A low BNP in an undifferentiated breathless patient effectively rules out heart failure and redirects the workup to the lungs.","A raised BNP does not diagnose heart failure — it indicates ventricular wall stress from many causes. Echocardiography is needed to confirm.","Obesity lowers BNP: in a markedly obese breathless patient, a 'normal' value should be interpreted with caution.","If the patient is on sacubitril/valsartan, measure NT-proBNP instead — the drug raises BNP by design and makes it uninterpretable.","BNP and NT-proBNP cut-offs are completely different numbers. Check which test your laboratory reports before applying a threshold."],
    rel:["ntprobnp","troponin","creatinine","ck"],
    src:["NICE chronic heart failure BNP referral thresholds; standard acute-setting rule-out values"]
